from collections import OrderedDict


class Policy:
    def __init__(self, capacity_bytes):
        self.capacity = max(0, int(capacity_bytes))
        self.recent = OrderedDict()
        self.frequent = OrderedDict()
        self.ghost_recent = OrderedDict()
        self.ghost_frequent = OrderedDict()
        self.recent_bytes = 0
        self.frequent_bytes = 0
        self.used = 0
        self.target = self.capacity // 2
        self.serial = 0
        self.ghost_bytes = 0
        self.ghost_limit = max(64, min(1 << 20, 2 * max(1, self.capacity)))
        self.ghost_count_limit = 4096

    def _drop_ghost(self, key):
        value = self.ghost_recent.pop(key, None)
        if value is not None:
            self.ghost_bytes -= value[0]
        value = self.ghost_frequent.pop(key, None)
        if value is not None:
            self.ghost_bytes -= value[0]

    def _remember_ghost(self, key, size, kind):
        self._drop_ghost(key)
        self.serial += 1
        value = (max(1, int(size)), self.serial)
        if kind == 1:
            self.ghost_recent[key] = value
        else:
            self.ghost_frequent[key] = value
        self.ghost_bytes += value[0]
        self._trim_ghosts()

    def _trim_ghosts(self):
        while (self.ghost_bytes > self.ghost_limit or
               len(self.ghost_recent) + len(self.ghost_frequent) > self.ghost_count_limit):
            if not self.ghost_recent and not self.ghost_frequent:
                break
            if not self.ghost_frequent:
                source = self.ghost_recent
            elif not self.ghost_recent:
                source = self.ghost_frequent
            elif next(iter(self.ghost_recent.values()))[1] <= next(iter(self.ghost_frequent.values()))[1]:
                source = self.ghost_recent
            else:
                source = self.ghost_frequent
            _, value = source.popitem(last=False)
            self.ghost_bytes -= value[0]

    def _adjust_target(self, kind):
        if self.capacity <= 0:
            return
        recent_ghost_bytes = sum(v[0] for v in self.ghost_recent.values())
        frequent_ghost_bytes = sum(v[0] for v in self.ghost_frequent.values())
        if kind == 1:
            delta = self.capacity if recent_ghost_bytes == 0 else max(1, min(self.capacity, frequent_ghost_bytes // recent_ghost_bytes or 1))
            self.target = min(self.capacity, self.target + delta)
        else:
            delta = self.capacity if frequent_ghost_bytes == 0 else max(1, min(self.capacity, recent_ghost_bytes // frequent_ghost_bytes or 1))
            self.target = max(0, self.target - delta)

    def _evict_one(self, kind):
        if not self.recent and not self.frequent:
            return None
        choose_recent = False
        if self.recent:
            if not self.frequent:
                choose_recent = True
            elif kind == 1:
                choose_recent = self.recent_bytes >= self.target
            elif kind == 2:
                choose_recent = self.recent_bytes > self.target
            else:
                choose_recent = self.recent_bytes > self.target
        if choose_recent:
            key, size = self.recent.popitem(last=False)
            self.recent_bytes -= size
            self.used -= size
            self._remember_ghost(key, size, 1)
            return key
        if self.frequent:
            key, size = self.frequent.popitem(last=False)
            self.frequent_bytes -= size
            self.used -= size
            self._remember_ghost(key, size, 2)
            return key
        key, size = self.recent.popitem(last=False)
        self.recent_bytes -= size
        self.used -= size
        self._remember_ghost(key, size, 1)
        return key

    def _make_room(self, incoming, kind):
        evicted = []
        while self.used + incoming > self.capacity:
            key = self._evict_one(kind)
            if key is None:
                break
            evicted.append(key)
        return evicted

    def access(self, key, size, now):
        key = int(key)
        size = max(0, int(size))

        if key in self.recent:
            old_size = self.recent.pop(key)
            self.recent_bytes -= old_size
            self.used -= old_size
            resident = True
        elif key in self.frequent:
            old_size = self.frequent.pop(key)
            self.frequent_bytes -= old_size
            self.used -= old_size
            resident = True
        else:
            resident = False

        if resident:
            if size <= 0 or size > self.capacity:
                return [key]
            evicted = self._make_room(size, 0)
            if self.used + size > self.capacity:
                return evicted + [key]
            self._drop_ghost(key)
            self.frequent[key] = size
            self.frequent_bytes += size
            self.used += size
            return evicted

        ghost_kind = 1 if key in self.ghost_recent else 2 if key in self.ghost_frequent else 0
        if size <= 0 or size > self.capacity:
            return []
        if ghost_kind:
            self._adjust_target(ghost_kind)
            self._drop_ghost(key)

        evicted = self._make_room(size, ghost_kind)
        if self.used + size > self.capacity:
            return evicted
        if ghost_kind:
            self.frequent[key] = size
            self.frequent_bytes += size
        else:
            self.recent[key] = size
            self.recent_bytes += size
        self.used += size
        return evicted
